      </nav>

      <!-- Folder listing -->
      <div class="flex-1 min-h-0 overflow-y-auto rounded-lg border border-base-content/10 divide-y divide-base-content/10">
        <div v-if="loading" class="flex items-center justify-center gap-2 p-6 text-xs opacity-70">
